class Solution {
public:
    int maxWeight(int n, vector<vector<int>>& edges,
                  int k, int t) {

        // DAG with n nodes cannot have a path
        // containing n or more edges.
        if (k >= n)
            return -1;

        if (k == 0)
            return 0;

        // dp[v][s] = true if a path ending at v
        // has total weight s using current edge count.
        vector<bitset<601>> dp(n), next(n);

        // A path can start at any node.
        for (int i = 0; i < n; ++i)
            dp[i].set(0);

        // Add one edge in each iteration.
        for (int step = 1; step <= k; ++step) {

            for (int i = 0; i < n; ++i)
                next[i].reset();

            for (const auto& e : edges) {
                int u = e[0];
                int v = e[1];
                int w = e[2];

                // Extend all reachable sums at u.
                next[v] |= (dp[u] << w);
            }

            dp.swap(next);
        }

        // Find maximum reachable weight < t.
        for (int sum = t - 1; sum >= 0; --sum) {
            for (int v = 0; v < n; ++v) {
                if (dp[v].test(sum))
                    return sum;
            }
        }

        return -1;
    }
};
